import{_ as t,o as a,c as r,am as n}from"./chunks/framework.yj4qiWdr.js";const s="/skill-issue/assets/save-progress-in-exam.C4_r1Zma.png",h=JSON.parse('{"title":"Consignes de l’examen CRTO","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/notes/Exam-Instructions.md","filePath":"crto/liham/notes/Exam-Instructions.md"}'),o={name:"crto/liham/notes/Exam-Instructions.md"};function i(d,e,l,c,u,p){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="consignes-de-l-examen-crto" tabindex="-1">Consignes de l’examen CRTO <a class="header-anchor" href="#consignes-de-l-examen-crto" aria-label="Permalink to &quot;Consignes de l’examen CRTO&quot;">​</a></h1><h2 id="demarrer-l-examen" tabindex="-1">Démarrer l’examen <a class="header-anchor" href="#demarrer-l-examen" aria-label="Permalink to &quot;Démarrer l’examen&quot;">​</a></h2><p>Dans le menu du cours, ouvrir la leçon <strong>Red Team Operator Exam</strong>.</p><blockquote><p><strong>Ne pas quitter la page de l’examen</strong> pendant son déroulement. Ouvrir le cours dans un autre onglet ou une autre fenêtre.</p></blockquote><p>Le <strong>Lab ID</strong> figure en bas du panneau d’instructions. Le communiquer en cas de demande au support.</p><hr><h2 id="scenario-de-l-examen" tabindex="-1">Scénario de l’examen <a class="header-anchor" href="#scenario-de-l-examen" aria-label="Permalink to &quot;Scénario de l’examen&quot;">​</a></h2><ul><li>Scénario <strong>assume-breach</strong> : aucun Beacon préalablement lancé, mais un accès à une machine <strong>foothold</strong> du réseau interne.</li><li>Le Beacon doit être déployé manuellement. <strong>Il peut être nécessaire de contourner les protections du poste au préalable.</strong></li><li>Le panneau d’instructions précise l’<strong>operational objective</strong> et les <strong>rules of engagement</strong> (hôtes exclus du périmètre et restrictions).</li></ul><hr><h2 id="bareme" tabindex="-1">Barème <a class="header-anchor" href="#bareme" aria-label="Permalink to &quot;Barème&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Élément</th><th>Points</th></tr></thead><tbody><tr><td>Objectif opérationnel</td><td>50 pts</td></tr><tr><td>Respect de l’OPSEC</td><td>50 pts</td></tr><tr><td><strong>Seuil de réussite</strong></td><td><strong>85 pts</strong></td></tr></tbody></table><blockquote><p><strong>Atteindre l’objectif ne suffit pas : les points OPSEC comptent aussi.</strong><strong>Un score OPSEC trop faible entraîne l’échec, même si l’objectif est atteint.</strong></p></blockquote><hr><h2 id="criteres-de-notation-opsec" tabindex="-1">Critères de notation OPSEC <a class="header-anchor" href="#criteres-de-notation-opsec" aria-label="Permalink to &quot;Critères de notation OPSEC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Critère</th><th>Cause de pénalité</th><th>Mesure préventive</th></tr></thead><tbody><tr><td><strong>Blocage par Defender / AppLocker</strong></td><td>Blocage de l’exécution d’un payload par l’antivirus</td><td>Vérifier l’Artifact Kit et le Resource Kit avant l’examen</td></tr><tr><td><strong>Connexion sortante depuis un processus inhabituel</strong></td><td>Callback HTTP d’un Beacon depuis un processus qui n’effectue normalement pas de requêtes Web</td><td>Utiliser un processus habituel (browser, svchost, dllhost) et configurer <code>spawnto</code> et <code>ppid</code></td></tr><tr><td><strong>Indicateurs Cobalt Strike par défaut</strong></td><td>Noms de named pipes par défaut et technique d’injection standard</td><td>Personnaliser <code>post-ex.pipename</code> et <code>process-inject</code> dans le Malleable C2 Profile</td></tr><tr><td><strong>Lateral Movement suspect</strong></td><td><code>jump psexec</code> / événements de création de services</td><td>Privilégier <code>jump winrm64</code>, puis <code>remote-exec wmi</code> ; utiliser PsExec en dernier recours</td></tr><tr><td><strong>Handles LSASS suspects</strong></td><td>Handle direct sur LSASS depuis un processus non-système</td><td>Privilégier le BOF <code>nanodump</code> ; éviter l’accès direct à LSASS avec Mimikatz</td></tr><tr><td><strong>Désactivation des protections</strong></td><td>Désactivation de Defender ou Windows Firewall</td><td><strong>Ne pas désactiver Defender ou Firewall : pénalité automatique</strong></td></tr></tbody></table><hr><h2 id="hotes-hors-perimetre-—-echec-immediat" tabindex="-1">Hôtes hors périmètre — Échec immédiat <a class="header-anchor" href="#hotes-hors-perimetre-—-echec-immediat" aria-label="Permalink to &quot;Hôtes hors périmètre — Échec immédiat&quot;">​</a></h2><blockquote><p><em>&quot;Une alerte déclenchée sur un hôte hors périmètre entraîne l’échec, même si l’objectif opérationnel a été atteint.&quot;</em></p></blockquote><p><strong>Lire les rules of engagement avant toute action.</strong> Identifier le périmètre avant tout Lateral Movement. Un hôte visible n’est pas nécessairement autorisé.</p><hr><h2 id="limites-de-temps" tabindex="-1">Limites de temps <a class="header-anchor" href="#limites-de-temps" aria-label="Permalink to &quot;Limites de temps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limite</th><th>Valeur</th></tr></thead><tbody><tr><td>Temps de Lab</td><td>24 heures cumulées</td></tr><tr><td>Fenêtre calendaire</td><td>7 jours pour terminer et soumettre</td></tr><tr><td>Délai entre deux tentatives</td><td>7 jours</td></tr><tr><td>Temps actif avant disponibilité de la sauvegarde</td><td>15 à 20 minutes</td></tr></tbody></table><hr><h2 id="sauvegarde-de-la-progression-—-deux-options-a-distinguer" tabindex="-1">Sauvegarde de la progression — Deux options à distinguer <a class="header-anchor" href="#sauvegarde-de-la-progression-—-deux-options-a-distinguer" aria-label="Permalink to &quot;Sauvegarde de la progression — Deux options à distinguer&quot;">​</a></h2><img src="'+s+`" width="860"><table tabindex="0"><thead><tr><th>Bouton</th><th>Résultat</th></tr></thead><tbody><tr><td><strong>Exit Lab → Save Progress And Exit</strong></td><td>VM sauvegardées, environnement suspendu — <strong>sans risque de clôture</strong></td></tr><tr><td><strong>Exit Lab → End Lab</strong></td><td><strong>Fin immédiate et irréversible de la tentative d’examen</strong></td></tr></tbody></table><blockquote><p><strong>Rester actif 15 à 20 minutes avant de pouvoir utiliser Save Progress And Exit.</strong> Ne démarrer l’examen que lorsque l’on est prêt : fermer immédiatement l’environnement peut mettre fin à la tentative.</p></blockquote><hr><h2 id="persistence-necessaire-—-ne-pas-dependre-uniquement-de-save-progress" tabindex="-1">Persistence nécessaire — Ne pas dépendre uniquement de Save Progress <a class="header-anchor" href="#persistence-necessaire-—-ne-pas-dependre-uniquement-de-save-progress" aria-label="Permalink to &quot;Persistence nécessaire — Ne pas dépendre uniquement de Save Progress&quot;">​</a></h2><blockquote><p><em>&quot;Ne pas compter sur cette fonction pour conserver les Beacons en cours, notamment ceux d’une chaîne P2P. Prévoir une persistence adaptée comme dans un environnement réel.&quot;</em></p></blockquote><p>Après une reprise, une chaîne Beacon SMB/P2P peut être interrompue. La persistence doit survivre au redémarrage. La configurer <strong>avant</strong> toute pause.</p><hr><h2 id="soumission-et-notation" tabindex="-1">Soumission et notation <a class="header-anchor" href="#soumission-et-notation" aria-label="Permalink to &quot;Soumission et notation&quot;">​</a></h2><ul><li>Cliquer sur <strong>Submit</strong> en bas du panneau d’instructions pour terminer l’examen et lancer la notation.</li><li><strong>Submit est définitif</strong> : éviter tout clic accidentel.</li><li>Ne pas quitter ni fermer la page pendant la notation, qui peut durer plusieurs minutes.</li><li>Après la notation, cliquer sur <strong>Update &amp; Close</strong> pour transmettre le résultat à la plateforme — <strong>sans cette étape, la certification ne peut pas être réclamée.</strong></li></ul><hr><h2 id="liste-de-verification-avant-l-examen" tabindex="-1">Liste de vérification avant l’examen <a class="header-anchor" href="#liste-de-verification-avant-l-examen" aria-label="Permalink to &quot;Liste de vérification avant l’examen&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>[ ] Lire les rules of engagement et identifier les hôtes hors périmètre</span></span>
<span class="line"><span>[ ] Se connecter en SSH au team server et mettre à jour le Malleable C2 Profile (stage, post-ex, process-inject)</span></span>
<span class="line"><span>[ ] Adapter l’Artifact Kit (patch.c), compiler et contrôler avec ThreatCheck</span></span>
<span class="line"><span>[ ] Compiler le Resource Kit, adapter template.x64.ps1 et contrôler AMSI avec ThreatCheck</span></span>
<span class="line"><span>[ ] Charger artifact.cna et resources.cna dans le CS Script Manager</span></span>
<span class="line"><span>[ ] Vérifier le callback Beacon avec Defender activé avant les actions sur cible</span></span>
<span class="line"><span>[ ] Éviter le processus spawnto par défaut rundll32.exe</span></span>
<span class="line"><span>[ ] Configurer un motif de named pipes personnalisé dans post-ex.pipename</span></span>
<span class="line"><span>[ ] Préparer la persistence à mettre en place après le premier check-in Beacon</span></span></code></pre></div>`,37)]))}const g=t(o,[["render",i]]);export{h as __pageData,g as default};
